cd /app && cat <<'EOF' > app/mailers/user_mailer.rb
class UserMailer < ApplicationMailer
  def email_verification(user, token)
    @user = user
    @account = user.account
    @verification_url = "#{frontend_url}/verify-email?account=#{ERB::Util.url_encode(@account.subdomain)}&token=#{ERB::Util.url_encode(token)}"

    mail(
      to: @user.email,
      subject: "Verify your email for #{@account.name}"
    )
  end

  def password_reset(user, token)
    @user = user
    @account = user.account
    @reset_url = "#{frontend_url}/reset-password?account=#{ERB::Util.url_encode(@account.subdomain)}&token=#{ERB::Util.url_encode(token)}"

    mail(
      to: @user.email,
      subject: "Reset your password for #{@account.name}"
    )
  end

  def invitation(invitation, token)
    @invitation = invitation
    @account = invitation.account
    @invited_by = invitation.invited_by
    @accept_url = "#{frontend_url}/accept-invitation?account=#{ERB::Util.url_encode(@account.subdomain)}&token=#{ERB::Util.url_encode(token)}"

    mail(
      to: @invitation.email,
      subject: "You have been invited to join #{@account.name}"
    )
  end

  private

  def frontend_url
    (ENV["HELPDESK_FRONTEND_URL"].presence || "http://localhost:3001").sub(%r{/+\z}, "")
  end
end
EOF

cat <<'EOF' > app/views/user_mailer/invitation.html.erb
<p>Hi,</p>

<p><%= @invited_by.name %> has invited you to join <%= @account.name %> as a <%= @invitation.role %>.</p>

<p>Accept your invitation by clicking the link below:</p>

<p><a href="<%= @accept_url %>"><%= @accept_url %></a></p>
EOF

cat <<'EOF' > app/views/user_mailer/invitation.text.erb
